CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenant(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_code VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE project(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),project_no VARCHAR(80) NOT NULL,name VARCHAR(300) NOT NULL,region_code VARCHAR(20) NOT NULL,region_level VARCHAR(20) NOT NULL,majors JSONB NOT NULL DEFAULT '[]',status VARCHAR(24) NOT NULL DEFAULT 'DRAFT',tender_date DATE,contract_date DATE,UNIQUE(tenant_id,project_no));
CREATE TABLE basis_pack(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES project(id),version_no INT NOT NULL,region_code VARCHAR(20) NOT NULL,region_level VARCHAR(20) NOT NULL,major VARCHAR(40) NOT NULL,effective_date DATE NOT NULL,measurement_standard_version VARCHAR(80) NOT NULL,pricing_standard_version VARCHAR(80) NOT NULL,quota_pack_version VARCHAR(80),rule_version_scope VARCHAR(30) NOT NULL,precision_rule_version VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',content_hash CHAR(64),locked_by BIGINT,locked_at TIMESTAMPTZ,UNIQUE(project_id,version_no));
CREATE TABLE basis_source(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,basis_pack_id BIGINT NOT NULL REFERENCES basis_pack(id),source_id VARCHAR(80) NOT NULL,title VARCHAR(500) NOT NULL,doc_no VARCHAR(120),issuer VARCHAR(200),source_type VARCHAR(30) NOT NULL,source_url TEXT,file_hash CHAR(64),license_status VARCHAR(20) NOT NULL,verified BOOLEAN NOT NULL DEFAULT FALSE,effective_from DATE,effective_to DATE,UNIQUE(basis_pack_id,source_id));
CREATE TABLE project_document(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES project(id),document_type VARCHAR(50) NOT NULL,title VARCHAR(500) NOT NULL,version_no INT NOT NULL,file_uri TEXT NOT NULL,file_hash CHAR(64) NOT NULL,classification VARCHAR(24) NOT NULL,source_type VARCHAR(30) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'UPLOADED',uploaded_by BIGINT NOT NULL,uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE extracted_field(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL REFERENCES project_document(id),field_key VARCHAR(160) NOT NULL,field_value JSONB,source_page INT,bbox JSONB,confidence NUMERIC(5,4),extractor_name VARCHAR(80),extractor_version VARCHAR(80),confirmation_status VARCHAR(24) NOT NULL DEFAULT 'PENDING',confirmed_by BIGINT,confirmed_at TIMESTAMPTZ,source_ref TEXT);
CREATE TABLE component(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES project(id),drawing_document_id BIGINT REFERENCES project_document(id),component_type VARCHAR(40) NOT NULL,code VARCHAR(80),level VARCHAR(40),params JSONB NOT NULL,geom JSONB,confidence NUMERIC(5,4),verified_by BIGINT,verified_at TIMESTAMPTZ,version_no INT NOT NULL DEFAULT 1);
CREATE TABLE boq_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES project(id),major VARCHAR(40) NOT NULL,item_code VARCHAR(80),name VARCHAR(500) NOT NULL,feature JSONB NOT NULL DEFAULT '{}',unit VARCHAR(30) NOT NULL,quantity NUMERIC(24,8),quantity_caliber VARCHAR(20),source_ref TEXT,version_no INT NOT NULL DEFAULT 1,status VARCHAR(24) NOT NULL DEFAULT 'DRAFT');
CREATE TABLE quota_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,quota_pack_version VARCHAR(80) NOT NULL,major VARCHAR(40) NOT NULL,item_code VARCHAR(100) NOT NULL,name VARCHAR(500) NOT NULL,unit VARCHAR(30) NOT NULL,work_content TEXT,resource_consumption JSONB NOT NULL,source_ref TEXT NOT NULL,license_status VARCHAR(20) NOT NULL,valid_from DATE,valid_to DATE,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',UNIQUE(quota_pack_version,major,item_code));
CREATE TABLE quota_note(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,quota_item_id BIGINT NOT NULL REFERENCES quota_item(id),scope_level VARCHAR(20) NOT NULL,effect_type VARCHAR(20) NOT NULL CHECK(effect_type IN('FORBID','FACTOR','REPLACE','INFO')),note_text TEXT NOT NULL,priority INT NOT NULL,source_ref TEXT NOT NULL,valid_from DATE,valid_to DATE);
CREATE TABLE calc_rule(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,rule_code VARCHAR(120) NOT NULL,version VARCHAR(40) NOT NULL,major VARCHAR(40) NOT NULL,caliber VARCHAR(20) NOT NULL,component_type VARCHAR(40),unit VARCHAR(30) NOT NULL,expression_id VARCHAR(120) NOT NULL,params_schema JSONB NOT NULL,standard_ref TEXT NOT NULL,source_ref TEXT NOT NULL,valid_from DATE NOT NULL,valid_to DATE,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',UNIQUE(rule_code,version));
CREATE TABLE calc_run(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES project(id),boq_item_id BIGINT REFERENCES boq_item(id),basis_pack_id BIGINT NOT NULL REFERENCES basis_pack(id),rule_code VARCHAR(120) NOT NULL,rule_version VARCHAR(40) NOT NULL,engine_build VARCHAR(80) NOT NULL,input_snapshot JSONB NOT NULL,input_hash CHAR(64) NOT NULL,result_value NUMERIC(24,8),result_unit VARCHAR(30),precision_rule_version VARCHAR(80) NOT NULL,status VARCHAR(24) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE evidence(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,calc_run_id BIGINT REFERENCES calc_run(id),project_id BIGINT NOT NULL REFERENCES project(id),subject_type VARCHAR(40) NOT NULL,subject_id VARCHAR(100) NOT NULL,result_value NUMERIC(24,8),result_unit VARCHAR(30),formula_text TEXT NOT NULL,intermediate_values JSONB NOT NULL,source_refs JSONB NOT NULL,basis_pack_id BIGINT NOT NULL REFERENCES basis_pack(id),rule_version VARCHAR(40) NOT NULL,producer VARCHAR(30) NOT NULL,confirmer BIGINT,confirmed_at TIMESTAMPTZ,content_hash CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE material_price(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,region_code VARCHAR(20) NOT NULL,region_level VARCHAR(20) NOT NULL,major VARCHAR(40) NOT NULL,material_code VARCHAR(100),material_name VARCHAR(300) NOT NULL,spec VARCHAR(300),unit VARCHAR(30) NOT NULL,period_id VARCHAR(80) NOT NULL,price_tax_included NUMERIC(20,6),price_tax_excluded NUMERIC(20,6),tax_rate NUMERIC(9,6),delivery_scope VARCHAR(300),freight_included BOOLEAN,loss_included BOOLEAN,storage_included BOOLEAN,source_ref TEXT NOT NULL,source_hash CHAR(64),license_status VARCHAR(20) NOT NULL,valid_from DATE,valid_to DATE);
CREATE TABLE fee_rate_matrix(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,region_code VARCHAR(20) NOT NULL,region_level VARCHAR(20) NOT NULL,major VARCHAR(40) NOT NULL,project_class VARCHAR(80),tax_mode VARCHAR(30),rule_version_scope VARCHAR(30) NOT NULL,fee_item VARCHAR(100) NOT NULL,base_def VARCHAR(120) NOT NULL,rate NUMERIC(18,10),calc_formula TEXT,is_noncompetitive BOOLEAN NOT NULL DEFAULT FALSE,authority VARCHAR(200) NOT NULL,doc_no VARCHAR(120) NOT NULL,source_ref TEXT NOT NULL,valid_from DATE NOT NULL,valid_to DATE);
CREATE TABLE project_job(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES project(id),business_line VARCHAR(8) NOT NULL,basis_pack_id BIGINT NOT NULL REFERENCES basis_pack(id),round_no INT NOT NULL DEFAULT 1,stage VARCHAR(20) NOT NULL DEFAULT 'ST0',status VARCHAR(24) NOT NULL DEFAULT 'QUEUED',owner_id BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(project_id,business_line,round_no));
CREATE TABLE job_task(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,job_id BIGINT NOT NULL REFERENCES project_job(id),step_code VARCHAR(80) NOT NULL,actor_type VARCHAR(30) NOT NULL,actor_id BIGINT,input_snapshot JSONB NOT NULL,output_snapshot JSONB,status VARCHAR(24) NOT NULL DEFAULT 'QUEUED',retry_count INT NOT NULL DEFAULT 0,error_code VARCHAR(80),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE gate_record(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,job_id BIGINT NOT NULL REFERENCES project_job(id),gate_code VARCHAR(12) NOT NULL,result VARCHAR(16) NOT NULL,failed_rules JSONB NOT NULL DEFAULT '[]',evidence_ids JSONB NOT NULL DEFAULT '[]',judged_by BIGINT,judged_at TIMESTAMPTZ NOT NULL DEFAULT now(),exception_approval_id BIGINT);
CREATE TABLE audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenant(id),actor_id BIGINT NOT NULL,action VARCHAR(80) NOT NULL,object_type VARCHAR(80) NOT NULL,object_id VARCHAR(100),before_hash CHAR(64),after_hash CHAR(64),reason TEXT,trace_id VARCHAR(80),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_doc_project_type ON project_document(project_id,document_type,version_no);
CREATE INDEX idx_boq_project_major ON boq_item(project_id,major);
CREATE INDEX idx_calc_run_item ON calc_run(boq_item_id,rule_version,created_at);
CREATE INDEX idx_evidence_project_subject ON evidence(project_id,subject_type,subject_id);
CREATE INDEX idx_price_region_period ON material_price(region_code,major,period_id);
CREATE INDEX idx_fee_scope ON fee_rate_matrix(region_code,major,rule_version_scope,fee_item);
CREATE INDEX idx_job_status ON project_job(status,stage);
